def luhn_checksum(card_number):
    digits = [int(d) for d in card_number]
    checksum = 0
    for i, digit in enumerate(digits):
        if i % 2 == 0:
            digit *= 2
            if digit > 9:
                digit -= 9
        checksum += digit
    return checksum % 10 == 0

